import * as Sentry from "@sentry/node";
import { parseUpload } from "../lib/upload-parser.js";

Sentry.init({ dsn: process.env.SENTRY_DSN, release: process.env.VERCEL_GIT_COMMIT_SHA,
  sendDefaultPii: false, defaultIntegrations: false, tracesSampleRate: 0,
  beforeSend(event) {
    // Fictional demo only: never transmit upload contents, caller or request data.
    delete event.request; delete event.user; delete event.breadcrumbs; delete event.extra;
    return event;
  },
});

export default async function handler(request, response) {
  response.setHeader("Cache-Control", "no-store");
  const commit = process.env.VERCEL_GIT_COMMIT_SHA || null;
  if (request.method !== "POST") return response.status(405).json({ error: "post_required", commit });
  // A fixture selector deliberately replaces real uploads for this public demo.
  // Real personal files must not be sent to Sentry or the coding environment.
  const body = request.body;
  if (!body || Array.isArray(body) || typeof body !== "object" || Object.keys(body).length !== 1 || body.sample !== "plants") return response.status(400).json({ error: "fictional_sample_required", commit });
  try {
    const result = parseUpload("name,quantity\nfern,2\nrose,1\n");
    return response.status(200).json({ ...result, sample: "plants", commit });
  } catch {
    const eventId = Sentry.captureException(new Error("Fictional plant upload failed"), { tags: { errand_demo: "upload_lf_v1" }, fingerprint: ["errand-upload-lf-v1"] });
    const captured = await Sentry.flush(1500);
    return response.status(500).json({ error: "sample_upload_failed", captured, eventId, commit });
  }
}

// Deliberate hackathon fixture: LF-only CSV is currently rejected.
export function parseUpload(csv) {
  const lines = csv.trim().split("\r\n");
  if (lines.shift() !== "name,quantity" || lines.length === 0) throw Error("sample_upload_line_endings");
  const quantities = lines.map((line) => {
    const [name, quantity, extra] = line.split(",").map((part) => part.trim());
    if (!name || extra !== undefined || !/^[1-9]\d{0,3}$/.test(quantity ?? "")) throw Error("sample_upload_invalid_row");
    return Number(quantity);
  });
  return { rows: quantities.length, totalQuantity: quantities.reduce((a, b) => a + b, 0) };
}

import test from "node:test";
import assert from "node:assert/strict";
import { parseUpload } from "../lib/upload-parser.js";
test("sample CRLF CSV parses", () => assert.deepEqual(parseUpload("name,quantity\r\nfern,2\r\nrose,1\r\n"), { rows: 2, totalQuantity: 3 }));
